void main() async { WidgetsFlutterBinding.ensureInitialized(); await initializeDateFormatting('ar'); await NotificationService.instance.init(); runApp(const DailyPlannerApp()); }

class DailyPlannerApp extends StatelessWidget { const DailyPlannerApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'جدولي اليومي', theme: ThemeData(useMaterial3: true, fontFamily: 'sans', colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xff3d6b65), brightness: Brightness.light), scaffoldBackgroundColor: const Color(0xfff6f7f5)), home: const PlannerHome()); }

class PlannerHome extends StatefulWidget { const PlannerHome({super.key}); @override State<PlannerHome> createState() => _PlannerHomeState(); }
class _PlannerHomeState extends State<PlannerHome> {
  DateTime day = DateTime.now(); List<DailyTask> tasks = []; bool loading = true;
  String get dateKey => DateFormat('yyyy-MM-dd').format(day);
  String get heading => DateUtils.isSameDay(day, DateTime.now()) ? 'اليوم' : DateFormat('EEEE، d MMMM', 'ar').format(day);
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { setState(() => loading = true); tasks = await DatabaseService.instance.tasksFor(dateKey); if (tasks.isEmpty) { final templates = await DatabaseService.instance.recurringBefore(dateKey); for (final template in templates) { await DatabaseService.instance.insert(DailyTask(date: dateKey, text: template.text, color: template.color, timeMinutes: template.timeMinutes, status: null, repeatDaily: true, createdAt: DateTime.now().microsecondsSinceEpoch)); } tasks = await DatabaseService.instance.tasksFor(dateKey); } setState(() => loading = false); }
  Future<void> _add() async { final id = await DatabaseService.instance.insert(DailyTask(date: dateKey, text: '', color: 0, createdAt: DateTime.now().microsecondsSinceEpoch)); await _load(); }
  Future<void> _save(DailyTask t) async { if (t.text.trim().isEmpty) { if (t.id != null) await DatabaseService.instance.delete(t.id!); } else { await DatabaseService.instance.update(t); if (t.timeMinutes != null) await NotificationService.instance.schedule(t); } await _load(); }
  Future<void> _delete(DailyTask t) async { if (t.id != null) { await DatabaseService.instance.delete(t.id!); await NotificationService.instance.cancel(t.id!); await _load(); } }
  @override Widget build(BuildContext context) { final unset = tasks.where((t) => t.status == null).toList(), done = tasks.where((t) => t.status == 1).toList(), undone = tasks.where((t) => t.status == 0).toList(); return Scaffold(appBar: AppBar(title: Text(heading, style: const TextStyle(fontWeight: FontWeight.bold)), centerTitle: false, actions: [IconButton(onPressed: () => setState(() => day = day.subtract(const Duration(days: 1))), icon: const Icon(Icons.chevron_right)), IconButton(onPressed: () => setState(() => day = day.add(const Duration(days: 1))), icon: const Icon(Icons.chevron_left)), IconButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const SettingsPage())), icon: const Icon(Icons.settings_outlined))]), body: loading ? const Center(child: CircularProgressIndicator()) : RefreshIndicator(onRefresh: _load, child: ListView(padding: const EdgeInsets.fromLTRB(16, 12, 16, 28), children: [Text(DateFormat('d MMMM yyyy', 'ar').format(day), style: TextStyle(color: Colors.grey.shade600)), const SizedBox(height: 14), if (tasks.isEmpty) const EmptyState(), ...tasks.map((t) => TaskCard(task: t, onChanged: _save, onDelete: _delete)), const SizedBox(height: 10), FilledButton.icon(onPressed: _add, icon: const Icon(Icons.add), label: const Text('إضافة مهمة'), style: FilledButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 14))), const SizedBox(height: 22), Section(title: 'لم تُحدَّد حالتها', icon: Icons.help_outline, tasks: unset), Section(title: 'المهام المكتملة', icon: Icons.check_circle_outline, tasks: done), Section(title: 'المهام غير المكتملة', icon: Icons.radio_button_unchecked, tasks: undone)]))); }
}

class EmptyState extends StatelessWidget { const EmptyState({super.key}); @override Widget build(BuildContext context) => Container(padding: const EdgeInsets.all(24), margin: const EdgeInsets.only(bottom: 14), decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(20)), child: const Column(children: [Icon(Icons.edit_note, size: 50, color: Color(0xff6a9189)), SizedBox(height: 8), Text('ابدأ بكتابة مهام يومك', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 17)), SizedBox(height: 4), Text('أضف مهمة جديدة، وحدد وقتها وحالتها من البطاقة نفسها.')],)); }

class TaskCard extends StatefulWidget { final DailyTask task; final Future<void> Function(DailyTask) onChanged; final Future<void> Function(DailyTask) onDelete; const TaskCard({super.key, required this.task, required this.onChanged, required this.onDelete}); @override State<TaskCard> createState() => _TaskCardState(); }
class _TaskCardState extends State<TaskCard> { late TextEditingController c; late int color; late int? status; late int? minutes; late bool repeat;
 @override void initState() { super.initState(); c = TextEditingController(text: widget.task.text); color = widget.task.color; status = widget.task.status; minutes = widget.task.timeMinutes; repeat = widget.task.repeatDaily; }
 @override void dispose() { c.dispose(); super.dispose(); }
