 @override Widget build(BuildContext context) { final colors = [const Color(0xffe4f1ed), const Color(0xffffecd1), const Color(0xffe9e3f6), const Color(0xffffe0e2), const Color(0xffe0edf7)]; return Card(margin: const EdgeInsets.only(bottom: 10), elevation: 0, color: colors[color % colors.length], shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(18)), child: Padding(padding: const EdgeInsets.fromLTRB(14, 10, 8, 10), child: Column(children: [Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Expanded(child: TextField(controller: c, minLines: 1, maxLines: 5, textInputAction: TextInputAction.newline, decoration: const InputDecoration(hintText: 'اكتب المهمة هنا...', border: InputBorder.none), onChanged: (_) => save())), PopupMenuButton<int>(icon: const Icon(Icons.more_horiz), itemBuilder: (_) => [const PopupMenuItem(value: 99, child: Text('حذف المهمة'))], onSelected: (v) { if (v == 99) widget.onDelete(widget.task); })]), Row(children: [IconButton(tooltip: 'تحديد اللون', onPressed: () => showDialog(context: context, builder: (_) => AlertDialog(title: const Text('لون المهمة'), content: Wrap(spacing: 10, children: List.generate(colors.length, (i) => InkWell(onTap: () { setState(() => color = i); Navigator.pop(context); save(); }, child: CircleAvatar(backgroundColor: colors[i], child: color == i ? const Icon(Icons.check) : null))))), icon: const Icon(Icons.palette_outlined, size: 20)), IconButton(tooltip: 'وقت التذكير', onPressed: () async { final picked = await showTimePicker(context: context, initialTime: TimeOfDay(hour: (minutes ?? 9 * 60) ~/ 60, minute: (minutes ?? 9 * 60) % 60)); if (picked != null) { setState(() => minutes = picked.hour * 60 + picked.minute); save(); } }, icon: Icon(minutes == null ? Icons.schedule_outlined : Icons.alarm, size: 20)), if (minutes != null) Text('${(minutes! ~/ 60).toString().padLeft(2, '0')}:${(minutes! % 60).toString().padLeft(2, '0')}'), const Spacer(), IconButton(tooltip: 'متكرر يوميًا', onPressed: () { setState(() => repeat = !repeat); save(); }, icon: Icon(repeat ? Icons.repeat_on : Icons.repeat, size: 20)), DropdownButton<int?>(value: status, underline: const SizedBox(), hint: const Text('الحالة'), items: const [DropdownMenuItem<int?>(value: null, child: Text('دون تحديد')), DropdownMenuItem<int?>(value: 1, child: Text('مكتملة')), DropdownMenuItem<int?>(value: 0, child: Text('غير مكتملة'))], onChanged: (v) { setState(() => status = v); save(); })])]))); }
}

class Section extends StatelessWidget { final String title; final IconData icon; final List<DailyTask> tasks; const Section({super.key, required this.title, required this.icon, required this.tasks}); @override Widget build(BuildContext context) => ExpansionTile(title: Text('$title (${tasks.length})', style: const TextStyle(fontWeight: FontWeight.w600)), leading: Icon(icon), initiallyExpanded: tasks.isNotEmpty, children: tasks.isEmpty ? [const ListTile(title: Text('لا توجد مهام هنا'))] : tasks.map((t) => ListTile(title: Text(t.text, maxLines: 2, overflow: TextOverflow.ellipsis), subtitle: t.timeMinutes == null ? null : Text('${(t.timeMinutes! ~/ 60).toString().padLeft(2, '0')}:${(t.timeMinutes! % 60).toString().padLeft(2, '0')}')) .toList()); }

class SettingsPage extends StatefulWidget { const SettingsPage({super.key}); @override State<SettingsPage> createState() => _SettingsPageState(); }
class _SettingsPageState extends State<SettingsPage> { bool enabled = true; @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('الإعدادات')), body: ListView(children: [SwitchListTile(title: const Text('الإشعارات'), subtitle: const Text('تذكيرات محلية في الأوقات المحددة'), value: enabled, onChanged: (v) { setState(() => enabled = v); NotificationService.instance.enabled = v; }), const Divider(), const ListTile(title: Text('عن التطبيق'), subtitle: Text('جدولي اليومي\nنسخة محلية تعمل دون حساب أو اتصال بالإنترنت')), const ListTile(title: Text('اسم المطور'), subtitle: Text('شرف علي شرف'))])); }